const MISSIONS={
welcome:[T('Lass dir zeigen, wer heute für Empfang, deine Station und Rückfragen zuständig ist.','Find out who is responsible for reception, your station and questions today.','Repérez qui s’occupe de l’accueil, de votre rang et de vos questions aujourd’hui.'),T('Übe mit einem Kollegen die Begrüßung und das Begleiten zum Tisch.','Practise greeting a guest and escorting them to the table with a colleague.','Entraînez-vous avec un collègue à accueillir une personne et à l’accompagner à sa table.'),T('Bitte um Rückmeldung: Warst du gut verständlich, aufmerksam und unaufdringlich?','Ask for feedback: were you clear, attentive and unobtrusive?','Demandez un retour : étiez-vous clair, attentif et discret ?')],
briefing:[T('Nimm am Briefing teil und notiere die Änderungen für den heutigen Service.','Attend the briefing and note today’s changes.','Participez au briefing et notez les changements du jour.'),T('Lass dir ein aktuelles Gericht am Pass erklären: Produkt, Garung, Sauce und Garnitur.','Ask the kitchen to explain a current dish at the pass: ingredient, cooking method, sauce and garnish.','Faites-vous présenter un plat au passe : produit, cuisson, sauce et garniture.'),T('Prüfe, wo du die aktuelle Rezeptur und die bestätigten Allergenangaben findest.','Check where to find the current recipe and verified allergen information.','Vérifiez où trouver la recette à jour et les informations validées sur les allergènes.')],
mise:[T('Decke einen Tisch nach Hausstandard ein und prüfe Gläser, Besteck und Servietten.','Set a table to house standards and check glasses, cutlery and napkins.','Dressez une table selon les usages de la maison et vérifiez verres, couverts et serviettes.'),T('Bestücke deine Servicestation und zeige, wo Ersatzbesteck, Tabletts und Weinwerkzeug liegen.','Stock your station and locate spare cutlery, trays and wine tools.','Préparez votre console et repérez les couverts de réserve, plateaux et outils de service du vin.'),T('Lass den Tisch kontrollieren und übe Tisch- und Platznummern an einem Beispiel.','Have the table checked and practise identifying table and seat numbers.','Faites contrôler la table et exercez-vous aux numéros de table et de place.')],
safety:[T('Finde die Allergenunterlagen und kläre, wer verbindlich Auskunft geben darf.','Locate the allergen records and identify who is authorised to give information.','Trouvez les documents sur les allergènes et identifiez la personne habilitée à renseigner les convives.'),T('Spiele eine Bestellung mit Sesamallergie durch und gib Tisch, Platz und Anforderung eindeutig weiter.','Rehearse an order involving a sesame allergy and clearly pass on the table, seat and requirement.','Simulez une commande avec allergie au sésame et transmettez clairement table, place et demande.'),T('Lass dir erklären, wie die Küche die Alternative bestätigt und wie sie am Pass zugeordnet wird.','Ask how the kitchen confirms an alternative and identifies it at the pass.','Faites-vous expliquer comment la cuisine valide une alternative et l’identifie au passe.')],
senses:[T('Bereite nach Absprache drei verträgliche Proben vor: zum Beispiel Apfel, Zitronenwasser und ungesüßten Tee.','With permission, prepare three suitable samples, such as apple, lemon water and unsweetened tea.','Préparez, avec accord, trois échantillons adaptés : pomme, eau citronnée et thé non sucré, par exemple.'),T('Notiere jeweils getrennt: Duft, Grundgeschmack und Mundgefühl.','Record aroma, basic taste and mouthfeel separately for each.','Notez séparément les arômes, les saveurs et les sensations en bouche.'),T('Vergleiche deine Beobachtungen mit einem Kollegen, ohne eine gemeinsame Antwort erzwingen zu wollen.','Compare observations with a colleague without forcing agreement.','Comparez vos observations avec un collègue sans chercher à imposer une réponse commune.')],
describe:[T('Rieche an drei verfügbaren Zutaten, etwa Zitronenschale, Rosmarin und geröstetem Brot.','Smell three available ingredients, such as lemon zest, rosemary and toasted bread.','Sentez trois ingrédients disponibles, par exemple un zeste, du romarin et du pain grillé.'),T('Beschreibe jede Probe zunächst allgemein und dann mit einem konkreten Vergleich.','Describe each sample first by family, then with a specific comparison.','Décrivez chaque échantillon par sa famille, puis avec une comparaison précise.'),T('Formuliere für ein Hausgetränk einen kurzen Satz, den ein Gast ohne Vorwissen versteht.','Write one short description of a house drink that a guest can understand without prior knowledge.','Formulez une courte description d’une boisson de la maison, compréhensible sans connaissances préalables.')],
cooking:[T('Frage am Pass nach der genauen Zubereitung eines aktuellen Gerichts.','Ask at the pass how a current dish is prepared.','Demandez au passe comment un plat actuel est préparé.'),T('Kläre, welche Sauce und welche Textur den Geschmack besonders prägen.','Identify which sauce and texture most influence the flavour.','Identifiez la sauce et la texture qui marquent le plus la dégustation.'),T('Erkläre das Gericht einem Kollegen und lass sachliche Ungenauigkeiten korrigieren.','Explain the dish to a colleague and ask them to correct any inaccuracies.','Présentez le plat à un collègue et faites corriger les éventuelles imprécisions.')],
produce:[T('Wähle ein Fisch-, Gemüse- oder Fleischgericht aus der aktuellen Karte.','Choose a fish, vegetable or meat dish from the current menu.','Choisissez un plat de poisson, de légumes ou de viande sur la carte actuelle.'),T('Prüfe mit der Küche Herkunft, Produktbezeichnung und Zubereitung.','Check origin, precise product name and preparation with the kitchen.','Vérifiez avec la cuisine l’origine, le nom précis du produit et sa préparation.'),T('Notiere zwei belegte Informationen, die du einem Gast nennen kannst.','Note two verified facts you can share with a guest.','Notez deux informations vérifiées que vous pourrez donner à un convive.')],
wine:[T('Wähle mit der zuständigen Person zwei tatsächlich angebotene Weine aus.','Select two wines from the current list with the responsible colleague.','Choisissez deux vins de la carte avec le responsable.'),T('Vergleiche Stil, Herkunft, Preis und die passende Ausschankmenge; Verkostung ist freiwillig.','Compare style, origin, price and serving measure; tasting is optional.','Comparez style, origine, prix et quantité servie ; la dégustation reste facultative.'),T('Erkläre den Unterschied ohne Begriffe, die du selbst nicht sicher erläutern kannst.','Explain the difference without terms you cannot confidently explain.','Expliquez la différence sans employer de termes que vous ne maîtrisez pas.')],
pairing:[T('Wähle einen aktuellen Teller und zwei Begleitungen mit deinem Serviceleiter aus.','Choose a current dish and two pairings with your service manager.','Choisissez un plat actuel et deux accords avec votre responsable de salle.'),T('Vergleiche einen kleinen Bissen mit beiden Getränken; eine alkoholfreie Auswahl ist gleichwertig möglich.','Compare a small bite with both drinks; alcohol-free options are equally suitable.','Comparez une bouchée avec les deux boissons ; des options sans alcool conviennent tout autant.'),T('Begründe, welche Kombination du welchem Gast empfehlen würdest.','Explain which combination you would recommend to which guest.','Expliquez quel accord vous conseilleriez selon les préférences du convive.')],
zero:[T('Prüfe, welche alkoholfreien Begleitungen euer Haus anbietet und welche davon nachweislich 0,0 % haben.','Check your alcohol-free pairings and which are verified as 0.0%.','Vérifiez les accords sans alcool de la maison et ceux dont le taux de 0,0 % est confirmé.'),T('Lass dir Rezeptur, Serviertemperatur, Glas und Portionsgröße einer Begleitung zeigen.','Learn the recipe, serving temperature, glass and portion size for one pairing.','Découvrez la recette, la température, le verre et la quantité d’un accord.'),T('Präsentiere diese Begleitung so sorgfältig wie einen Wein.','Present the pairing with the same care as a wine.','Présentez cet accord avec autant de soin qu’un vin.')],
bottle:[T('Präsentiere eine geschlossene Flasche mit Produzent, Wein, Jahrgang, Größe und Preis.','Present a closed bottle with producer, wine, vintage, size and price.','Présentez une bouteille fermée : producteur, vin, millésime, format et prix.'),T('Übe Öffnen und Einschenken unter Anleitung; beginne mit einer geeigneten Übungsflasche.','Practise opening and pouring under supervision, starting with a suitable training bottle.','Exercez-vous à l’ouverture et au service sous supervision, avec une bouteille adaptée à l’entraînement.'),T('Lass Griff, Stand, Tropfenkontrolle und Ausschankmenge prüfen.','Have your grip, stance, drip control and serving measure checked.','Faites vérifier la prise en main, la position, la maîtrise des gouttes et la quantité servie.')],
consult:[T('Spielt ein Beratungsgespräch mit zwei unterschiedlichen Vorlieben.','Role-play a recommendation for two different preferences.','Simulez un conseil pour deux préférences différentes.'),T('Frage nach Stil und Preisrahmen und biete zwei passende Optionen an.','Ask about style and budget, then offer two suitable options.','Demandez le style souhaité et le budget, puis proposez deux options adaptées.'),T('Nenne Preis und Menge eindeutig und bestätige die Auswahl vor der Bestellung.','State price and measure clearly and confirm the choice before ordering.','Précisez le prix et la quantité, puis confirmez le choix avant la commande.')],
sequence:[T('Lass dir erklären, wie Bestellungen, Gangabrufe und Tischpausen bei euch weitergegeben werden.','Learn how your restaurant communicates orders, course calls and pauses.','Découvrez comment votre maison transmet les commandes, les envois et les pauses.'),T('Übe eine fiktive Bestellung mit Tisch, Platz, Gang und Sonderwunsch; nutze keinen echten Auftrag als Test.','Practise a fictional order with table, seat, course and request; do not use a live order for testing.','Exercez-vous avec une commande fictive : table, place, plat et demande particulière. N’utilisez pas une vraie commande pour tester.'),T('Begleite einen Gang unter Anleitung und prüfe vor dem Servieren die Zuordnung aller Teller.','Help serve a course under supervision and check every dish’s seat before serving.','Accompagnez l’envoi d’un plat sous supervision et vérifiez l’attribution des assiettes avant le service.')],
explain:[T('Lass die Beschreibung eines Tagesgerichts von der Küche bestätigen.','Have the kitchen confirm your description of a current dish.','Faites valider par la cuisine votre présentation d’un plat du jour.'),T('Präsentiere das Gericht in ungefähr 20 Sekunden und erkläre einen Fachbegriff in Alltagssprache.','Introduce it in about 20 seconds and explain one technical term in everyday language.','Présentez-le en une vingtaine de secondes et expliquez un terme technique simplement.'),T('Bitte um Rückmeldung zu Inhalt, Lautstärke, Blickkontakt und Länge.','Ask for feedback on content, volume, eye contact and length.','Demandez un retour sur le contenu, le volume de voix, le regard et la durée.')],
recovery:[T('Kläre, wer Ersatzgerichte, Preisnachlässe und andere Lösungen freigibt.','Find out who can authorise replacement dishes, discounts and other solutions.','Identifiez qui peut autoriser un remplacement, un geste commercial ou une autre solution.'),T('Übe eine Reklamation, ohne zu widersprechen oder die Schuld an andere weiterzugeben.','Practise handling a complaint without arguing or shifting blame.','Entraînez-vous à traiter une réclamation sans contredire ni rejeter la faute.'),T('Schließe das Gespräch mit einem konkreten nächsten Schritt ab und übe die Rückmeldung am Tisch.','Close with a specific next step and practise returning to update the guest.','Terminez par une prochaine étape précise et exercez-vous à revenir informer le convive.')],
cheese:[T('Prüfe bei drei angebotenen Käsen Milch, Herstellung und Reife anhand der Produktinformationen.','Check milk, production style and maturity for three cheeses against product information.','Vérifiez le lait, la fabrication et l’affinage de trois fromages à partir des fiches produits.'),T('Lass dir Portionierung, Werkzeug und die hygienische Handhabung zeigen.','Learn portioning, tools and hygienic handling.','Faites-vous montrer le portionnement, les outils et les gestes d’hygiène.'),T('Stelle eine Auswahl mit milder und kräftiger Option vor und begründe eine Begleitung.','Present a selection with mild and stronger options and explain a pairing.','Présentez une sélection douce et plus puissante, puis expliquez un accord.')],
tea:[T('Lerne die Kaffee- und Teeangebote, Portionsgrößen und koffeinfreien Alternativen eures Hauses kennen.','Learn your house coffees, teas, measures and caffeine-free options.','Découvrez les cafés, thés, quantités et alternatives sans caféine de la maison.'),T('Bereite ein Getränk nach Hausrezept unter Anleitung zu und prüfe das passende Geschirr.','Prepare one drink to the house recipe under supervision and check the correct serving ware.','Préparez une boisson selon la recette de la maison sous supervision et vérifiez la vaisselle adaptée.'),T('Erkläre, wie Allergien bei Milchalternativen und benutztem Zubehör berücksichtigt werden.','Explain how allergies are managed with milk alternatives and shared equipment.','Expliquez la gestion des allergies avec les boissons végétales et le matériel utilisé.')],
hygiene:[T('Lass dir Händehygiene, Reinigungsplan und die Trennung sauberer und benutzter Utensilien zeigen.','Review hand hygiene, the cleaning plan and separation of clean and used utensils.','Reprenez l’hygiène des mains, le plan de nettoyage et la séparation des ustensiles propres et utilisés.'),T('Finde Notfallkontakte und kläre den Umgang mit Scherben, Verbrennungen und gemeldeten Krankheitssymptomen.','Locate emergency contacts and learn the procedures for broken glass, burns and reported illness.','Repérez les contacts d’urgence et les procédures pour le verre cassé, les brûlures et les symptômes de maladie.'),T('Führe die Abschlusskontrolle deiner Station gemeinsam mit einer erfahrenen Person durch.','Complete your station’s closing check with an experienced colleague.','Effectuez le contrôle de fermeture de votre poste avec une personne expérimentée.')],
farewell:[T('Prüfe eine Übungsrechnung auf Tisch, Positionen, Mengen und Preise.','Check a training bill for table, items, quantities and prices.','Vérifiez une addition d’exercice : table, articles, quantités et prix.'),T('Übe getrennte Zahlung im Schulungsmodus oder auf Papier und kläre eure Datenschutzregeln.','Practise split payment in training mode or on paper and review your privacy rules.','Exercez-vous au partage d’addition en mode formation ou sur papier et reprenez les règles de confidentialité.'),T('Besprich nach einem begleiteten Service eine gelungene Handlung und einen nächsten Lernschritt.','After a supervised service, discuss one thing you did well and one next learning step.','Après un service accompagné, échangez sur un geste réussi et un prochain objectif.')]
};
UI.practiceTitle=T('Deine Aufgabe im Restaurant','Your task in the restaurant','Votre exercice au restaurant');
UI.practiceIntro=T('Erledige diese Schritte mit einer erfahrenen Person aus deinem Team. Hake ab, was du tatsächlich geübt oder geklärt hast.','Work through these steps with an experienced colleague. Tick only what you have actually practised or checked.','Réalisez ces étapes avec une personne expérimentée de votre équipe. Cochez uniquement ce que vous avez réellement pratiqué ou vérifié.');
UI.completeHint=T('Für den Abschluss brauchst du die richtige Antwort und die drei erledigten Praxisaufgaben. Deine Angaben bleiben bei dir; sie sind keine betriebliche Freigabe.','To complete this lesson, answer correctly and finish the three practical tasks. Your record stays private and does not constitute workplace sign-off.','Pour terminer, répondez correctement et réalisez les trois exercices pratiques. Votre suivi reste privé et ne vaut pas validation professionnelle.');
UI.journeyIntro=T('Zwanzig Einheiten für deine ersten Wochen im Service. Lerne die Grundlagen, entscheide in typischen Situationen und übe die Handgriffe mit deinem Team.','Twenty lessons for your first weeks in service. Learn the essentials, make decisions in familiar situations and practise with your team.','Vingt séquences pour vos premières semaines en salle. Découvrez les bases, réagissez à des situations concrètes et exercez-vous avec votre équipe.');
UI.notebook=T('Dein Notizbuch für den Service','Your service notebook','Votre carnet de service');
UI.labTitle=T('Was passt zu diesem Gericht?','What works with this dish?','Quel accord pour ce plat ?');
UI.aromas=T('Aromen erkennen und beschreiben','Recognising and describing aromas','Reconnaître et décrire les arômes');
UI.journey=T('Schritt für Schritt im Service ankommen.','Find your feet in service, step by step.','Prendre ses repères en salle, pas à pas.');
UI.know=T('Das solltest du wissen','What you need to know','Ce qu’il faut savoir');
UI.practice=T('Eine Übung zum Einstieg','A first exercise','Un premier exercice');
UI.done=T('abgeschlossen','completed','terminé');
UI.home=T('Die Kunst, gut zu bewirten.','The art of thoughtful service.','L’art de recevoir.');
UI.intro=T('Willkommen im Service. Hier lernst du, Gerichte zu erklären, passende Getränke zu empfehlen und deine Gäste aufmerksam durch den Abend zu begleiten. Mit Übungen, die du direkt im Restaurant ausprobieren kannst.','Welcome to the dining room. Learn to describe dishes, recommend drinks and look after your guests throughout the evening, with exercises you can put into practice in your restaurant.','Bienvenue en salle. Apprenez à présenter les plats, à conseiller les boissons et à prendre soin des convives tout au long du repas, avec des exercices à mettre en pratique au restaurant.');
UI.start=T('Deine erste Aufgabe öffnen','Open your first task','Découvrir votre premier exercice');
UI.finish=T('Aufgabe abschließen','Complete task','Terminer l’exercice');
UI.completedText=T('Du hast die digitalen Übungen und deine Praxisaufgaben abgeschlossen. Besprich mit dem Serviceleiter, was du bereits selbstständig übernehmen kannst und wo du noch Begleitung brauchst.','You have completed the digital exercises and practical tasks. Discuss with your service manager what you can now handle independently and where you still need support.','Vous avez terminé les exercices numériques et pratiques. Voyez avec votre responsable ce que vous pouvez désormais prendre en charge et ce qui demande encore un accompagnement.');
SOURCES.push({name:'Institut Lyfe · Mise en situation professionnelle',url:'https://www.institutlyfe.com/institut-lyfe/nos-lieux-de-mise-en-situation-professionnelle/',topic:T('Lernen in der praktischen Arbeit','Learning through practical work','Apprendre par la pratique')});
const titles={welcome:T('Gäste begrüßen und begleiten','Welcoming and seating guests','Accueillir et installer les convives'),mise:T('Die Station vorbereiten','Preparing your station','Préparer son poste'),wine:T('Wein verständlich erklären','Explaining wine clearly','Parler du vin simplement'),zero:T('Alkoholfreie Getränke empfehlen','Recommending alcohol-free drinks','Conseiller des boissons sans alcool'),produce:T('Die Produkte deiner Karte kennen','Knowing your menu’s ingredients','Connaître les produits de la carte'),consult:T('Herausfinden, was dem Gast gefällt','Understanding what your guest enjoys','Comprendre les goûts du convive'),explain:T('Ein Gericht vorstellen','Introducing a dish','Présenter un plat'),recovery:T('Mit Beschwerden umgehen','Handling complaints','Répondre aux réclamations'),farewell:T('Die Rechnung und der Abschied','The bill and the farewell','L’addition et le départ')};
for(const l of LESSONS){if(titles[l.id])l.title=titles[l.id];}
let taskChecks=read('taskChecks',{});
function canComplete(id){const l=LESSONS.find(l=>l.id===id);return selectedAnswers[id]===l.answer&&(taskChecks[id]||[]).filter(Boolean).length===3}
function missionHTML(id){return `<section class="mission-block"><div class="mission-heading"><div><h2>${txt(UI.practiceTitle)}</h2><p>${txt(UI.practiceIntro)}</p></div>${art(LESSONS.find(l=>l.id===id).art)}</div><fieldset><legend>${txt(T('Im Haus geübt oder geklärt','Practised or checked at work','Pratiqué ou vérifié sur place'))}</legend>${MISSIONS[id].map((s,i)=>`<label><input type="checkbox" data-task="${i}" data-id="${id}" ${(taskChecks[id]||[])[i]?'checked':''}><span>${txt(s)}</span></label>`).join('')}</fieldset><p class="hint">${txt(T('Du bist gerade nicht im Restaurant? Deine Antworten werden gespeichert. Setze die Praxisaufgaben bei deinem nächsten Dienst fort.','Not at the restaurant right now? Your answers are saved. Continue the practical tasks on your next shift.','Vous n’êtes pas au restaurant ? Vos réponses sont enregistrées. Reprenez les exercices pratiques lors de votre prochain service.'))}</p></section>`}
const baseLessonPage=lessonPage;
lessonPage=function(id){let html=baseLessonPage(id);if(!MISSIONS[id])return html;html=html.replace('<section class="lesson-end">',missionHTML(id)+'<section class="lesson-end">');if(!canComplete(id)&&!completed.includes(id))html=html.replace(/(<button class="primary" id="complete"[^>]*)(>)/,(_,a,b)=>a.includes('disabled')?a+b:a+' disabled'+b);return html};
const baseBind=bind;
bind=function(){baseBind();document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{let id=c.dataset.id;taskChecks[id]??=[false,false,false];taskChecks[id][+c.dataset.task]=c.checked;write('taskChecks',taskChecks);if(!c.checked&&completed.includes(id)){completed=completed.filter(x=>x!==id);write('completed',completed)}$('#complete').disabled=!canComplete(id)&&!completed.includes(id);if(!storageOK)$('#note-status').textContent=txt(UI.storageError)});};
const explainedLessonPage=lessonPage;
function nextInstruction(id){const l=LESSONS.find(x=>x.id===id),checks=(taskChecks[id]||[]).filter(Boolean).length;if(completed.includes(id))return txt(T('Diese Einheit ist abgeschlossen. Du kannst sie wiederholen oder zur nächsten Einheit wechseln.','This lesson is complete. Review it or move on to the next one.','Cette séquence est terminée. Vous pouvez la revoir ou passer à la suivante.'));if(selectedAnswers[id]!==l.answer)return txt(T('Lies zuerst die Einführung und beantworte anschließend die Frage. Bei einer falschen Antwort kannst du es erneut versuchen.','Read the introduction, then answer the question. If your answer is incorrect, you can try again.','Lisez d’abord l’introduction, puis répondez à la question. Vous pouvez réessayer si votre réponse est incorrecte.'));if(checks<3)return txt(T(`Die Frage ist beantwortet. Erledige noch ${3-checks} ${checks===2?'Praxisaufgabe':'Praxisaufgaben'} im Restaurant. Danach kannst du die Einheit abschließen.`,`The question is answered. Complete ${3-checks} more practical ${checks===2?'task':'tasks'} at the restaurant, then finish the lesson.`,`Vous avez répondu à la question. Réalisez encore ${3-checks} ${checks===2?'exercice pratique':'exercices pratiques'} au restaurant pour terminer la séquence.`));return txt(T('Alles erledigt. Du kannst noch eine freiwillige Notiz speichern oder die Aufgabe jetzt abschließen.','Everything is done. Save an optional note or complete the task now.','Tout est fait. Vous pouvez enregistrer une note facultative ou terminer l’exercice.'))}
lessonPage=function(id){let html=explainedLessonPage(id);const l=LESSONS.find(x=>x.id===id);if(!l)return html;const no=LESSONS.indexOf(l)+1;html=html.replace('<div class="lesson-layout">',`<section class="lesson-guide"><div><strong>${txt(T('Dein Ablauf','Your next steps','Votre déroulement'))}</strong><span>${txt(T('Einheit','Lesson','Séquence'))} ${no} / ${LESSONS.length}</span></div><p class="next-instruction">${nextInstruction(id)}</p><div class="step-nav">${[T('1. Einführung lesen','1. Read the introduction','1. Lire l’introduction'),T('2. Frage beantworten','2. Answer the question','2. Répondre à la question'),T('3. Im Restaurant üben','3. Practise at work','3. Pratiquer au restaurant')].map((s,i)=>`<button data-scroll="${['reading','decision','practice'][i]}">${txt(s)}</button>`).join('')}</div></section><div class="lesson-layout" id="reading">`);html=html.replace('<section class="exercise">','<section class="exercise" id="decision">').replace('<section class="mission-block">','<section class="mission-block" id="practice">');html=html.replace(/<div class="practice"><h2>.*?<\/h2><p>.*?<\/p><\/div><\/article>/,`<div class="actions"><button class="text-button" data-scroll="decision">${txt(T('Weiter zur Frage','Continue to the question','Passer à la question'))}${arrow}</button></div></article>`);html=html.replace(`<label for="reflection">${txt(UI.reflect)}</label>`,`<label for="reflection">${txt(UI.reflect)}</label><p class="hint">${txt(T('Freiwillig – eine persönliche Notiz für deinen nächsten Service.','Optional — a personal note for your next service.','Facultatif — une note personnelle pour votre prochain service.'))}</p>`);html=html.replace(`<p class="hint">${txt(UI.completeHint)}</p>`,`<p class="hint completion-status">${nextInstruction(id)}</p><a class="back" href="#journey">${txt(T('Praxis später erledigen und weitere Kapitel ansehen','Return to the practice later and browse more chapters','Reprendre la pratique plus tard et voir les autres chapitres'))}</a>`);if(selectedAnswers[id]===l.answer)html=html.replace(`<p>${txt(l.feedback)}</p>`,`<p>${txt(l.feedback)}</p><button class="text-button" data-scroll="practice">${txt(T('Weiter zu deinen Praxisaufgaben','Continue to your practical tasks','Passer aux exercices pratiques'))}</button>`);return html};
const explainedBind=bind;
bind=function(){explainedBind();document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>{const target=document.getElementById(b.dataset.scroll);target?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});document.querySelectorAll('[data-task]').forEach(c=>{const update=c.onchange;c.onchange=()=>{update();document.querySelectorAll('.next-instruction,.completion-status').forEach(el=>el.textContent=nextInstruction(c.dataset.id))}})};
render(false);
